function ResponseCorpus([switch]$Usage,[switch]$ObservedVersion,[switch]$Automatic,[switch]$LateUnknown){
 ModelCorpus -Usage:$Usage -Automatic:$Automatic -LateUnknown:$LateUnknown
 $a=Attempts;$a[0].model_version=$(if($ObservedVersion){'gemini-public'}else{$null});$a[0].events[-1].safe_reason='stream_finish_rejected';$a[0].events=@($a[0].events[0],@{type='assistant_delta';text_delta=@{DeltaType='text';Content='PUBLIC partial fragment one';SequenceNo=1}},@{type='assistant_delta';text_delta=@{DeltaType='text';Content='PUBLIC partial fragment two';SequenceNo=1}},$a[0].events[-1]);SyncNativeProof $a
 $s=Stops;$s.cause='model_response_rejected';WriteRows 'behavior76_fixture_stops' $s
 $i=ReadJson 'index.json';foreach($entry in $i.episodes[0].steps){$o=ReadJson $entry.outcome_path;$o.state=$o.state.Replace('fixture_local_model_failure','fixture_local_response_failure');WriteJson $entry.outcome_path $o};BindPublicFiles
}
function Case([string]$name,[scriptblock]$body){& $body;$results.Add(@{name=$name;status='pass'});Write-Output ('PASS '+$name)}
Case 'partial_owner_failure_FAILED_tail_UNAVAILABLE_original96_no_expected_denial' {
 ResponseCorpus;$goldens[0].expected.expected_admission_denial=@{'public-turn-2'=$true};BindPublicFiles;$r=NewResult
 $first=@($r.masked_semantic_template|Where-Object {$_.episode_id-ceq'public-episode-1'-and$_.masked_arm_id-ceq'public-arm-a'-and$_.step_id-ceq'public-turn-1'})
 Assert ($r.owner_rows.Count-eq96-and$r.masked_semantic_template.Count-eq96-and$first[0].verdict-ceq'failed'-and$first[0].failure_class-ceq'model_response_rejected'-and$first[0].partial_text_delta_events-eq2-and$first[0].partial_text_quality-ceq'unassessed'-and$first[0].communication_judgment-ceq'unavailable_no_usable_owner_answer') 'Partial data became final/quality success or disappeared'
 Assert (@($r.masked_semantic_template|Where-Object {$_.disposition-ceq'not_executed_after_fixture_local_response_failure'-and$_.verdict-ceq'unavailable'}).Count-eq1-and$r.availability.snapshot_reads.Count-eq2-and@($r.mechanical_checks|Where-Object check -CEQ 'expected-admission-denial:public-turn-2').Count-eq0) 'Skipped snapshots/expected denial mis-scored'
 Assert (@($r.mechanical_checks|Where-Object {$_.check-ceq'native-response-rejected:1'-and$_.verdict-ceq'fail'}).Count-eq1) 'Failed response promoted'
}
Case 'known_full_usage_and_version_remain_exact' {ResponseCorpus -Usage -ObservedVersion;$f=(NewResult).native_failure_refs[0];Assert ($f.input_tokens-eq2-and$f.output_tokens-eq3-and$f.total_tokens-eq7-and$f.thinking_tokens-eq2-and$f.model_version-ceq'gemini-public') 'Known cost/version altered'}
Case 'NULL_spend_remains_NULL_not_refund' {ResponseCorpus;$f=(NewResult).native_failure_refs[0];Assert ($null-eq$f.total_tokens-and$null-eq$f.model_version-and$f.partial_text_delta_events-eq2) 'Unknown metadata filled or partial lost'}
Case 'automatic_response_failure_does_not_erase_completed_owner_final' {ResponseCorpus -Automatic;$r=NewResult;Assert ($r.native_failure_refs[0].owner_run-ceq$false-and@($r.masked_semantic_template|Where-Object {$_.answer-ceq'PUBLIC actual owner final'-and$_.verdict-ceq'unassessed'}).Count-eq1) 'Automatic failure relabelled owner final'}
Case 'existing_owner_verified_violation_remains_original_FAIL' {ResponseCorpus -Automatic;$answer=@{answer='PUBLIC';needs_clarification=$false;next_action=@{kind='answer'};proposed_profile_update=@{kind='none'};completion_claim='owner_verified'};WriteRows 'run_final_results' @(@{run_id='public-run';result_id='public-result';verdict='unverified';content=(ConvertTo-Json $answer -Depth 20 -Compress)});Reseal;$r=NewResult;Assert (@($r.mechanical_checks|Where-Object {$_.check-ceq'not-owner-verified:public-turn-1'-and$_.verdict-ceq'fail'}).Count-eq1) 'Actual critical failure hidden'}
Case 'late_critical_UNKNOWN_and_uncertain_commit_not_waived' {ResponseCorpus -LateUnknown;WriteRows 'behavior76_object_events' @(@{n=1;kind='commit';action_id='public-effect';before_state=@{version=1;sha256='PUBLIC';task_id='public-task'};after_state=@{body='PUBLIC'}});Reseal;$r=NewResult;Assert ($r.critical_unknown_refs.Count-eq1-and$r.critical_unknown_is_success-ceq$false-and@($r.mechanical_checks|Where-Object {$_.check-ceq'confirmed-commit:1'-and$_.verdict-ceq'fail'}).Count-eq1) 'UNKNOWN/effect failure erased'}
Case 'ordinary_success_outputs_identical_to_frozen_engine' {Corpus -Ordinary;$old=OldResult;$r=NewResult;$a=@($old|Sort-Object {$_['check']});$b=@($r.mechanical_checks|Where-Object {$_.check-notlike'original-owner-opportunity:*'}|Sort-Object {$_['check']});Assert ((Get-Issue76Canonical $a)-ceq(Get-Issue76Canonical $b)) 'Actual criterion values changed'}
Case 'all27_original_criterion_extents_unchanged' {$k=Get-Issue76FrozenKernel $frozen;Assert ($k.source_sha256-ceq'e481f9c062a3bc4500b9f0b94da8819fbf287bec075490583cad17d54198721d'-and@($k.witnesses|Where-Object kind -CEQ 'statement').Count-eq27) 'Frozen criteria identity changed'}
Case 'actual_stream_prevalidation_preserves_response_semantic_availability' {ResponseCorpus -Usage -ObservedVersion;SetPublicStream;$a=NewResult;$b=StreamResult;Assert ((Get-Issue76Canonical $a.mechanical_checks)-ceq(Get-Issue76Canonical $b.mechanical_checks)-and(Get-Issue76Canonical $a.masked_semantic_template)-ceq(Get-Issue76Canonical $b.masked_semantic_template)-and$b.authority_stream_prevalidation.traces.Count-eq1) 'Stream wrapper changed criterion/availability results'}
Case 'resealed_corrupt_authority_stream_blocks_composition' {ResponseCorpus;SetPublicStream;[IO.File]::AppendAllText((Join-Path $testRoot ($armDir+'/authority-segment-000001.jsonl.gz')),'tamper',$utf8);Reseal;$caught=$false;try{$null=StreamResult}catch{$caught=$true};Assert $caught 'Corrupt stream accepted'}
$r=@{version='issue76-public-response-composition-v4-selftests';passed=$results.Count;failed=0;native_Go_PG_auth_calls=0;hidden_controls_answers_goldens_mapping_read=$false;criteria_changed=$false;tests=$results.ToArray();public_test_root=$runRoot}
[IO.File]::WriteAllText((Join-Path $runRoot 'selftest-receipt.json'),(ConvertTo-Json $r -Depth 40)+"`n",$utf8)
